"""Person-reference detector for layer 15's MLP down-projection, component 1861.

What it does: this component writes a "a person is being referred to here" signal into
the residual stream. It is strongest on words that name a person by role or title
(author, artist, father, wife, manager, ...), and on the punctuation right after a title
or initial ("Dr." "Mr." "J."), where a person's name is expected next. It is moderate on
singular person pronouns (he, him, his, she, her), on "who", "someone", "said" and "by",
and small on other punctuation after a name. Ordinary tokens sit near a small baseline (0.06).

The program predicts the activation from the words alone: it reads only the current
token and the one before it (within the same document) and returns a fixed value for
the category it falls in. The weights were set by hand from category means on training rows.
It explains only a few percent of the variance: most of the activation is diffuse.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

# Singular third-person pronouns (he, his, him ...) and first/second-person ones.
THIRD_PRONOUNS = {"he", "him", "his", "himself", "she", "her", "hers", "herself"}
OTHER_PRONOUNS = {"i", "me", "my", "you", "your", "mine", "yours"}

# Words for people: roles, occupations, family, kinship, titles.
PEOPLE = set(
    """
    man men woman women person people boy girl child children son daughter father mother
    dad mom parent husband wife brother sister friend friends teacher student students
    doctor patient patients artist author authors writer poet painter singer actor actress
    director producer manager coach player players leader leaders owner founder president
    governor minister senator king queen prince princess lord lady judge lawyer officer
    soldier chef pilot driver worker employee customer client user partner colleague
    neighbor citizen expert scientist engineer designer inventor professor politician
    mayor captain speaker guy
    """.split()
)

# Titles that come right before a surname: "Dr. Smith", "Mr. Jones".
TITLES = {
    "Mr", "Mrs", "Dr", "Ms", "Prof", "Professor", "Judge", "Sir", "Lord", "Saint", "St",
    "Pope", "Rev", "Governor", "President", "Senator", "King", "Queen", "Captain", "General",
}

# Words that can be followed by a person's name: who, someone, said, by (credits).
PERSON_CUES = {"who", "whom", "someone", "anyone", "person", "said", "by"}

WEIGHTS = {
    "third_pronoun": 2.6,
    "other_pronoun": 0.9,
    "person_word": 3.2,
    "person_cue": 1.4,
    "possessive_s": 0.8,
    "title_then_period": 5.0,
    "title_then_other": 1.2,
    "initial_then_period": 2.0,
    "person_then_punct": 1.5,
    "cap_then_punct": 0.3,
    "other": 0.06,  # typical value of ordinary tokens
}

PUNCT = {",", ".", "and"}


def _word(text: str) -> str:
    return text.strip()


def _is_name_word(word: str) -> bool:
    return len(word) > 1 and word[0].isupper() and word[1:].islower()


def step(carry, prefix, upstream: Mapping):
    t = prefix.position
    word = _word(prefix.token_strings[t])
    prev = ""
    if t > 0 and prefix.document_ids[t - 1] == prefix.document_ids[t]:
        prev = _word(prefix.token_strings[t - 1])

    # The word itself.
    if word.lower() in THIRD_PRONOUNS:
        value = WEIGHTS["third_pronoun"]
    elif word in PEOPLE:
        value = WEIGHTS["person_word"]
    elif word in PERSON_CUES:
        value = WEIGHTS["person_cue"]
    elif word.lower() in OTHER_PRONOUNS:
        value = WEIGHTS["other_pronoun"]
    elif word in ("'s", "’s"):
        value = WEIGHTS["possessive_s"]
    else:
        value = WEIGHTS["other"]

    # Punctuation or "and" right after a person-word, title, initial or name.
    if word in PUNCT:
        if prev in TITLES and word == ".":
            value = WEIGHTS["title_then_period"]
        elif prev in TITLES:
            value = max(value, WEIGHTS["title_then_other"])
        elif len(prev) == 1 and prev.isupper() and word == ".":
            value = max(value, WEIGHTS["initial_then_period"])
        elif prev in PEOPLE or prev.lower() in THIRD_PRONOUNS:
            value = max(value, WEIGHTS["person_then_punct"])
        elif _is_name_word(prev):
            value = max(value, WEIGHTS["cap_then_punct"])
    return carry, float(value)

"""Explainer program for p-82af68dd@100000/layers.15.mlp.down_proj:1882.

What the component does (as far as a readable rule can say): it is a weak, mostly
negative feature that sits on words which set up an upcoming verb or a human actor.
Its strongest negative values come on
  * a subject pronoun (he, she, they, I, we) that opens an embedded clause
    ("...decided that he", "if he", "because they"), and other subject pronouns;
  * "to" right after a verb of trying, deciding or seeming ("tries to", "decided to",
    "going to", "failed to"), i.e. a control verb whose subject does the action;
  * object pronouns and possessives (him, them, his, their), and modal or auxiliary
    verbs (will, can, is, was, not), more weakly.
Its positive values come on "to" after a noun for the one who acts or benefits
("opportunity to", "chance to", "students to", "users to"), where the actor is someone
other than the subject.

The program is a lookup on the current word and the word before it. It predicts
the value per position, with no state carried between positions. It does not
explain most of the variance: almost all of the component's variance sits on
ordinary tokens with small values that no word list captures. Surface word identity
explains essentially none of that variance out of sample.
"""

READS = ()

# Subject pronouns: the actor of the next verb.
SUBJECT_PRONOUNS = {" he", " she", " they", " I", " we", " He", " She", " They", " We"}
# Words that open an embedded clause, after which a subject pronoun is typically embedded.
CLAUSE_OPENERS = {
    " that", " if", " because", " when", " as", " what", " which", " but", " and", " so",
    " how", " where", " before", " while", " until", " since", " though", " whether",
}
OBJECT_PRONOUNS = {" him", " them", " me", " us"}
POSSESSIVES = {" his", " her", " their", " its", " my", " your", " our", " His", " Their"}
MODALS_AND_AUXILIARIES = {
    " will", " can", " would", " could", " may", " must", " should", " might", " shall",
    " is", " was", " has", " have", " had", " be", " been", " not",
}
# Verbs whose subject also performs the infinitive that follows them ("tries to", "decided to").
CONTROL_VERBS = {
    " tries", " try", " tried", " agreed", " decided", " decides", " decide", " going",
    " failed", " fails", " refused", " seemed", " seems", " wanted", " needs", " tends",
    " tend", " attempted", " designed", " intended", " offered", " got", " happy", " nice",
    " able", " seek",
}
# Nouns for the one who acts or benefits, before an infinitive "to" with another actor.
ACTOR_NOUNS = {
    " opportunity", " chance", " time", " students", " users", " viewers", " audience",
    " people", " employees", " reluctant", " willing", " allowed", " way", " ability",
    " freedom", " opportunities",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1]
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    before = prefix.token_strings[-2] if same_doc else " <start>"

    if word in SUBJECT_PRONOUNS:
        value = -1.0 if before in CLAUSE_OPENERS else -0.6
    elif word in OBJECT_PRONOUNS:
        value = -0.4
    elif word in POSSESSIVES:
        value = -0.3
    elif word == " to":
        if before in CONTROL_VERBS:
            value = -1.0
        elif before in ACTOR_NOUNS:
            value = 0.8
        else:
            value = -0.15
    elif word in MODALS_AND_AUXILIARIES:
        value = -0.15
    else:
        value = 0.0
    return carry, float(value)

"""Component L15 MLP down_proj:1889 — a "be-verb" (copula / auxiliary) detector.

What it does, in plain terms:
- It is strongly NEGATIVE on forms of the verb "to be" (is, are, was, were, be,
  been, being, am, and the 're / 'm contractions): the more a form of "be" is
  the main predicate-linking verb of a clause, the more negative.
- The size depends on what comes just before it. After a modal or "to"/"has"/
  "have" ("can be", "must be", "to be", "has been") it is most negative; after
  an existential or demonstrative subject ("there is", "this is", "what is") it
  is only mildly negative.
- Adverbs placed between a "be" form and its predicate ("is not", "are also",
  "is often") are moderately negative too.
- Elsewhere it is near zero, with a mild positive lean on finite auxiliaries and
  subject pronouns ("could", "had", "has", "it", "they").

The program only looks at the current token and the one before it (in the same
document), so it is causal and needs no state.
"""

BE_FORMS = {" be", " is", " are", " was", " were", " been", " being", " am",
            "'re", "'m", "’re", "’m"}
EXISTENTIAL = {" there", " There", " this", " This", " that", " That", " what",
               " What", " here", " Here"}
MODAL_LIKE = {" can", " could", " may", " might", " will", " would", " should",
              " must", " shall", " has", " have", " had", " to", " cannot", " not"}
ADVERBS = {" not", " also", " still", " only", " so", " often", " typically",
           " then", " therefore", " ever", " usually", " specifically", " always",
           " never", " just", " very", " too", " actually"}
AUX_AND_PRONOUNS = {" may", " might", " could", " would", " should", " must", " has",
                    " had", " have", " got", " get", " It", " it", " He", " She",
                    " They", " he", " she", " they"}

READS = ()


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    # the token before, only if it is in the same document
    prev = ""
    if len(prefix.token_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2]

    if tok in BE_FORMS:
        if prev in EXISTENTIAL:
            value = -1.0
        elif prev in MODAL_LIKE:
            value = -5.5
        else:
            value = -4.0
    elif tok in ADVERBS and prev in BE_FORMS:
        value = -2.0
    elif tok in AUX_AND_PRONOUNS:
        value = 0.4
    else:
        value = 0.0
    return carry, float(value)

"""Lean on a few words, by how the component's activation averages over them.

The component is a dense projection of the layer-15 MLP hidden state, and its activation
is mostly context, not token identity. The strongest word-level tendencies are:
- coordinating conjunctions " and" and " or" sit above zero;
- sentence-opening prepositions and connectives ("In", "For", "As", "When", "After", ...)
  sit below zero;
- everything else is predicted at 0.
"""

READS = ()

CONJUNCTIONS = {" and": 0.10, " or": 0.24}
OPENERS = {
    " In": -0.29, "In": -0.26, " For": -0.32, "For": -0.2, " As": -0.28, "As": -0.36,
    " When": -0.2, "When": -0.28, " After": -0.27, " While": -0.37, " Although": -0.41,
    " Here": -0.2, "Here": -0.29, "The": -0.18, " The": -0.1,
}
VALUES = {**CONJUNCTIONS, **OPENERS}


def step(carry, prefix, upstream):
    return carry, VALUES.get(prefix.token_strings[-1], 0.0)

"""Layer 15 MLP down-projection, component 1904: a weak detector for words that tie a
sentence back to what came before, above all the anaphoric "In THIS case" / "During THESE
years" construction, and "when"-style temporal connectives.

It is mostly silent. The strongest responses come on a determiner or quantifier that
follows an opening preposition or a sentence boundary: "In this case" (this), "During this
time" (this), "At these", "In such", "Both", "Each", and temporal openers "When", "During",
"While", "After" at the start of a clause. Weaker positive responses come on clause-linking
words ("or", "that", "as", "if", "in", "at") and commas. Words inside an "if ..." clause
(the word after "if you") are pushed slightly negative.

The program predicts that value token by token from the words just before. It reads only
the prefix, and it resets at each document boundary.
"""

READS = ()

DEMONSTRATIVES = {"this", "these", "those", "such"}
DISTRIBUTIVES = {"both", "each", "every", "either", "neither", "all", "any"}
TEMPORAL = {"when", "during", "while", "after", "before", "since", "once", "until"}
OPENERS = {"in", "at", "on", "for", "from", "within", "throughout", "of", "by", "with"}
BOUNDARIES = {".", "!", "?", ":", ";", "\n"}
LINKERS = {"or": 0.5, "that": 0.35, "as": 0.25, "if": 0.2, "in": 0.2, "at": 0.2, "by": 0.15, "with": 0.15}
PUNCTUATION = {",", ".", "!", "?", ":", ";", "(", ")", '"'}


def step(carry, prefix, upstream):
    """Activation at this position: a small baseline, plus weights by word class, with
    extra weight when the word follows an opening preposition or sentence boundary."""
    t = prefix.position
    if t == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0
    words = [s.strip().lower() for s in prefix.token_strings[max(0, t - 3):]]
    word = words[-1]
    before = words[-2] if len(words) > 1 else ""
    after_opener = before in OPENERS or before in BOUNDARIES
    value = 0.06
    if word in DEMONSTRATIVES:
        value += 1.1 + (1.0 if after_opener else 0.0)
    elif word in DISTRIBUTIVES:
        value += 0.4 + (0.45 if after_opener else 0.0)
    elif word in TEMPORAL:
        value += 0.4 + (1.1 if after_opener else 0.0)
    elif word in OPENERS and before in BOUNDARIES:
        value += 0.5
    value += LINKERS.get(word, 0.0)
    if "if" in words[:-1] and word not in PUNCTUATION:
        value -= 0.2
    return None, value

"""Layer 15 MLP down_proj, component 1911: a rough word-class guess.

What the component does, as far as word classes go: it is high on content words that
continue a name or a compound ("Santa Claus", "Northwestern University", "AI system",
"likelihood function", "version 3") and on capitalized words, nouns and CJK characters
in general. It is near zero on spaces, function words ("very", "such", "for") and most
punctuation. Its large spikes depend on context this rule does not see, so it captures
only about 1-2% of the variance; the rule is a description of where it tends to be high,
not a model of it.

Each position gets a level from its own token and, for names and compounds, the token
before it (in the same document). Levels are the mean activations measured on training
text, rounded.
"""

from functools import lru_cache

import wordfreq
import wordnet


@lru_cache(maxsize=None)
def bare(token):
    """The token's letters, lowercased, or '' if it is not a plain word."""
    word = token.strip()
    return word.lower() if word.isalpha() and len(word) >= 2 else ""


@lru_cache(maxsize=None)
def is_noun(token):
    word = bare(token)
    return bool(word) and "noun" in wordnet.parts_of_speech(word)


@lru_cache(maxsize=None)
def is_function_word(token):
    word = bare(token)
    return bool(word) and wordfreq.zipf_frequency(word, "en") > 5.5 and not is_noun(token)


def is_capitalized(token):
    return bool(bare(token)) and token.strip()[:1].isupper()


def is_cjk(token):
    return any("一" <= ch <= "鿿" for ch in token)


def is_name_or_noun_or_number(token):
    """A content token that can end a name or compound: a capitalized word, a noun or a number."""
    return is_capitalized(token) or is_noun(token) or token.strip().isdigit()


def level(prev, cur, same_document):
    """The predicted activation for token `cur`, given the token before it."""
    if not cur.strip():
        return 0.04  # spaces and newlines
    if is_cjk(cur):
        return 0.39
    if not cur.strip().isalnum():
        return 0.12  # punctuation and symbols
    if is_function_word(cur):
        return 0.06
    after = same_document and bool(prev.strip())
    if cur.strip().isdigit():
        # a number right after a name or noun: "Claus 3", "python 3"
        return 0.9 if after and is_name_or_noun_or_number(prev) and not prev.strip().isdigit() else 0.27
    if is_capitalized(cur):
        if after and is_capitalized(prev):
            return 0.85  # the end of a name: "Santa Claus", "Northwestern University"
        if after and is_name_or_noun_or_number(prev):
            return 0.5
        return 0.39
    if is_noun(cur):
        if after and is_noun(prev):
            return 0.49  # the end of a compound noun: "AI system", "likelihood function"
        if after and (is_capitalized(prev) or prev.strip().isdigit()):
            return 0.5
        return 0.33
    return 0.2


READS = ()


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    cur = tokens[-1]
    same_document = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = tokens[-2] if same_document else ""
    return None, level(prev, cur, same_document)
